<include file="Public:header"/>	<style type="text/css">		.time{color: green;float: left;margin-right: 20px;}		.content{height: 50px;}		.content-desc{float: left;}		.name{margin-bottom: 5px;}	</style>	<form id="myform" method="post" action="{pigcms{:U('position_audit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="position_id" value="{pigcms{$detail.position_id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">用户昵称</th>				<td width="35%">{pigcms{$detail.nickname}</td>				<th width="15%">手机号</th>				<td width="35%">{pigcms{$detail.phone}</td>			</tr>			<tr>				<th width="15%">排名</th>				<td width="35%">{pigcms{$detail.name}</td> 				<th width="15%">价格</th>				<td width="35%">{pigcms{$detail.price}</td>			</tr>						<tr>				<th width="15%">下单时间</th>				<td width="15%">{pigcms{$detail.order_time|date='Y-m-d H:i:s',###}</td>				<th width="15%">支付时间</th>				<td width="15%"><if condition="$detail['paid'] eq 0">{pigcms{$detail.pay_time|date='Y-m-d H:i:s',###}<else/>未支付</if></td>			</tr>			<tr>				<th width="15%">支付方式</th>				<td width="35%"><if condition="$detail['pay_type']">{pigcms{$detail.pay_type}<else/>余额支付</if></td>				<th width="15%">实付金额</th>				<td width="35%">{pigcms{$detail.price}</td>			</tr>					</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form><include file="Public:footer"/>